"use client";

import AuthFrame from "@/components/auth/AuthFrame";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { AlertCircle, ArrowLeft, ArrowRight, CheckCircle2, Mail, ShieldCheck } from "lucide-react";
import Link from "next/link";
import { useState } from "react";

type ApiResponse = {
  message?: string;
  errors?: Record<string, string[]>;
};

function getApiMessage(data: ApiResponse, fallback: string) {
  return data.message || Object.values(data.errors ?? {})[0]?.[0] || fallback;
}

export default function ForgotPassword() {
  const [email, setEmail] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setErrorMessage("");
    setSuccessMessage("");

    try {
      const response = await fetch("/api/auth/forgot-password", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email }),
      });

      const data: ApiResponse = await response.json();

      if (response.ok) {
        setSuccessMessage(
          data.message || "Nếu email tồn tại trong hệ thống, BloomShop sẽ gửi mật khẩu mới đến email đó."
        );
      } else {
        setErrorMessage(getApiMessage(data, "Chưa thể gửi email khôi phục mật khẩu."));
      }
    } catch {
      setErrorMessage("Lỗi kết nối đến máy chủ. Vui lòng thử lại sau.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthFrame
      mode="forgot"
      bannerBadge="Khôi phục tài khoản"
      bannerTitle="Lấy lại quyền truy cập BloomShop thật nhanh."
      bannerDescription="BloomShop sẽ gửi mật khẩu tạm thời đến email tài khoản, sau đó yêu cầu bạn đổi mật khẩu mới khi đăng nhập."
    >
      <Card className="flex w-full flex-col border-border bg-card shadow-md">
        <CardHeader className="space-y-3 pb-5">
          <div className="inline-flex w-fit items-center gap-2 rounded-md border border-primary/20 bg-primary/10 px-3 py-1 text-xs font-semibold text-primary">
            <ShieldCheck className="h-3.5 w-3.5" />
            Bảo mật tài khoản
          </div>
          <div className="space-y-2">
            <CardTitle className="text-3xl font-bold text-foreground">
              Quên mật khẩu
            </CardTitle>
            <CardDescription className="text-base leading-relaxed">
              Nhập email đã đăng ký để nhận mật khẩu tạm thời từ BloomShop.
            </CardDescription>
          </div>
        </CardHeader>

        <CardContent className="flex-1">
          {errorMessage && (
            <div className="mb-5 flex items-start gap-3 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{errorMessage}</span>
            </div>
          )}

          {successMessage && (
            <div className="mb-5 flex items-start gap-3 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">
              <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0" />
              <span>{successMessage}</span>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-2">
              <label htmlFor="email" className="text-sm font-semibold text-foreground">
                Email
              </label>
              <div className="relative">
                <Mail className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  id="email"
                  name="email"
                  type="email"
                  placeholder="nguyenvana@example.com"
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  required
                  className="pl-10"
                />
              </div>
            </div>

            <Button
              type="submit"
              size="lg"
              disabled={isLoading}
              className="h-11 w-full rounded-lg bg-primary text-primary-foreground shadow-md hover:bg-primary/90"
            >
              {isLoading ? (
                <>
                  <div className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
                  Đang gửi email...
                </>
              ) : (
                <>
                  Gửi mật khẩu mới
                  <ArrowRight className="h-4 w-4" />
                </>
              )}
            </Button>
          </form>
        </CardContent>

        <CardFooter className="justify-center border-t border-border pt-6">
          <Link href="/login" className="inline-flex items-center gap-2 text-sm font-semibold text-primary hover:underline">
            <ArrowLeft className="h-4 w-4" />
            Quay lại đăng nhập
          </Link>
        </CardFooter>
      </Card>
    </AuthFrame>
  );
}
